import {defaults,render} from './design-engine.js';
import {loadScene} from './scene-library.js';
const canvas=document.querySelector('#launchCanvas');if(canvas){const k=canvas.dataset.category;const s={...defaults(k),collection:k==='radio'?'radio-launch-v2':'clan-launch-v2',accent:k==='radio'?'#65edff':'#68f4d0',secondary:k==='radio'?'#78aaff':'#8cb6ff'},name=document.querySelector('#launchName'),color=document.querySelector('#launchColor');color.value=s.accent;function draw(){s.texts[0].text=name.value||'DEIN NAME';s.accent=color.value;s.texts[1].color=color.value;render(canvas.getContext('2d'),s,{watermark:true});}name.addEventListener('input',draw);color.addEventListener('input',draw);Promise.all([loadScene(s),document.fonts.ready]).then(draw).catch(()=>{const p=document.createElement('p');p.textContent='Das Paketmotiv konnte nicht geladen werden. Bitte die Seite erneut laden.';canvas.after(p)});draw();}
